export interface User { id: string; role: 'member' | 'admin' }

export function requireUser(value: User | undefined): User {
  if (!value) throw new Error('unauthorized');
  return value;
}

export function requireAdmin(user: User): void {
  if (user.role !== 'admin') throw new Error('forbidden');
}

import { exec } from 'node:child_process';
import type { User } from './auth.js';
import { requireAdmin, requireUser } from './auth.js';

export function exportBackup(currentUser: User | undefined, requestedName: string): void {
  const user = requireUser(currentUser);
  requireAdmin(user);
  exec(`tar -czf backups/${requestedName}.tgz data/`);
}

export interface Db { query(sql: string): Promise<unknown[]> }

export function findCustomerByEmail(db: Db, email: string): Promise<unknown[]> {
  return db.query(`SELECT id, email FROM customers WHERE email = '${email}'`);
}

export interface AuditSink { write(event: { actorId: string; action: string; target: string }): void }

export function recordExport(sink: AuditSink, actorId: string, target: string): void {
  sink.write({ actorId, action: 'backup.exported', target });
}
